import {escapeHTML as esc} from './workspace.js';
const svg=name=>`<svg viewBox="0 0 24 24" aria-hidden="true"><use href="#${name}"/></svg>`;
const models={ready:'Qwen3 0.6B · 本地就绪',starting:'本地模型启动中',stopped:'本地模型未启动','missing-model':'尚未下载模型','missing-runtime':'尚未安装本地运行环境',error:'本地模型暂不可用'};
export class ProjectFileView{
 constructor({desktop,getProjects,setView,refresh,notify}){
  Object.assign(this,{desktop,getProjects,setView,refresh,notify});this.data={files:[],projects:[],roots:[],errors:[],model:{state:'stopped'}};this.code='';this.category='materials';this.search='';this.settings=false;this.mode='workspace';this.loading=false;this.loadAgain=false;this.peekOpen=false;this.refreshTimer=null;this.openGroups=new Set();this.navSignature='';
  document.addEventListener('click',e=>this.click(e));
  document.addEventListener('input',e=>{if(e.target.matches('[data-library-search]')){this.search=e.target.value;this.paintBody();}});
  document.addEventListener('change',e=>this.change(e));
  document.addEventListener('toggle',e=>{if(e.target.matches?.('[data-file-group]')){e.target.open?this.openGroups.add(e.target.dataset.fileGroup):this.openGroups.delete(e.target.dataset.fileGroup);}},true);
  if(desktop?.files){desktop.onFilesChanged(()=>{clearTimeout(this.refreshTimer);this.refreshTimer=setTimeout(()=>this.load(),180);});desktop.onLayout(l=>this.applyLayout(l));this.ready=this.init().catch(e=>notify(e.message));}
 }
 async init(){this.applyLayout(await this.desktop.layout());await this.desktop.files('catalog',{projects:this.getProjects().map(p=>({code:p.code,name:p.name}))});await this.load();}
 async load(){if(this.loading){this.loadAgain=true;return;}this.loading=true;try{this.data=await this.desktop.files('snapshot');if(!this.code)this.code=this.data.projects[0]?.code||'';const signature=JSON.stringify(this.data.files.filter(f=>f.state==='linked').map(f=>[f.id,f.name,f.projectCode,f.linkedCodes]));const navChanged=signature!==this.navSignature;this.navSignature=signature;const viewSignature=JSON.stringify(this.settings?{roots:this.data.roots,model:this.data.model,errors:this.data.errors}:{code:this.code,category:this.category,search:this.search,files:this.files().map(f=>[f.id,f.name,f.material,f.projectCode,f.stage,f.version,f.state,f.reason])});const contentChanged=viewSignature!==this.viewSignature;const focused=document.activeElement;const editing=focused?.matches('input,select')&&focused.closest('.file-peek,.file-workspace');if(!editing){this.viewSignature=viewSignature;this.refresh({navChanged,contentChanged});if(this.peekOpen&&contentChanged)this.paintPeek();}}catch(e){this.notify(e.message);}finally{this.loading=false;if(this.loadAgain){this.loadAgain=false;this.load();}}}
 async syncProjects(){if(this.desktop?.files){await this.desktop.files('catalog',{projects:this.getProjects().map(p=>({code:p.code,name:p.name}))});}}
 applyLayout(layout){this.mode=layout.mode;this.peekOpen=Boolean(layout.peek);document.documentElement.dataset.windowMode=layout.mode;document.getElementById('shell').classList.toggle('sidebar-collapsed',layout.mode!=='workspace');document.getElementById('filePeek').hidden=!this.peekOpen;const toggle=document.getElementById('collapseSidebar');toggle.setAttribute('aria-label',this.mode==='workspace'?'收起为文件侧栏':'展开工作区');toggle.setAttribute('aria-expanded',String(this.mode==='workspace'));if(this.peekOpen)this.paintPeek();}
 async setMode(mode){if(this.desktop?.layout){this.applyLayout(await this.desktop.layout({mode,peek:false}));}else{document.getElementById('shell').classList.toggle('sidebar-collapsed');}}
 async show(code=this.code,category='materials'){this.code=category==='pending'&&code===''?'':code||this.data.projects[0]?.code||'';this.category=category;this.settings=false;this.search='';if(this.mode!=='workspace'){this.peekOpen=true;this.applyLayout(await this.desktop.layout({peek:true}));this.paintPeek();}else this.setView('files');}
 async showSettings(){this.settings=true;if(this.mode!=='workspace'){this.peekOpen=true;this.applyLayout(await this.desktop.layout({peek:true}));this.paintPeek();}else this.setView('files');}
 projectName(){return this.data.projects.find(p=>p.code===this.code)?.name||this.code||'项目文件';}
 pendingFiles(){return this.data.files.filter(f=>f.state==='pending'&&(!this.code||f.projectCode===this.code||f.linkedCodes?.includes(this.code)));}
 files(){let files=this.data.files.filter(f=>f.state!=='ignored');if(this.category==='pending')files=this.pendingFiles();else if(this.category==='borrow')files=files.filter(f=>f.borrowed&&(!this.code||f.projectCode===this.code||f.linkedCodes?.includes(this.code)||!f.linkedCodes?.length));else files=files.filter(f=>f.state==='linked'&&(!this.code||f.projectCode===this.code||f.linkedCodes?.includes(this.code))&&(this.category==='sheets'?f.kind==='sheet':f.kind!=='sheet'));
 const query=this.search.trim().toLocaleLowerCase();if(query)files=files.filter(f=>(f.name+' '+f.path+' '+f.material).toLocaleLowerCase().includes(query));return files.sort((a,b)=>b.mtime-a.mtime);}
 navProjects(){return this.data.projects.filter(p=>this.data.files.some(f=>f.state==='linked'&&(f.projectCode===p.code||f.linkedCodes?.includes(p.code))));}
 projectFiles(code){return this.data.files.filter(f=>f.state==='linked'&&(f.projectCode===code||f.linkedCodes?.includes(code))).sort((a,b)=>b.mtime-a.mtime);}
 tabs(){return `<div class="file-tabs" role="group" aria-label="文件类型">${[['materials','物料'],['sheets','阶段表格'],['borrow','借用'],['pending','待确认']].map(([key,label])=>`<button data-file-category="${key}" aria-pressed="${key===this.category}">${label}${key==='pending'?`<span>${this.pendingFiles().length||''}</span>`:''}</button>`).join('')}</div>`;}
 toolbar(compact=false){return `<header class="file-view-heading"><div><strong>${esc(this.settings?'文件来源':this.projectName())}</strong>${!this.settings&&this.code?`<span>${esc(this.code)}</span>`:''}</div><div>${!this.settings?'<button class="file-icon-button" data-file-settings aria-label="文件来源设置" title="文件来源设置">'+svg('sliders')+'</button>':''}${compact?'<button class="file-icon-button" data-file-close aria-label="收起文件集">×</button>':''}</div></header>`;}
 searchBar(){return `<div class="file-search-row"><input type="search" data-library-search value="${esc(this.search)}" placeholder="搜索文件" aria-label="搜索项目文件">${this.data.projects.length?`<select data-file-project-select aria-label="选择文件项目">${this.category==='pending'?'<option value="">全部项目</option>':''}${this.data.projects.map(p=>`<option value="${esc(p.code)}" ${p.code===this.code?'selected':''}>${esc(p.code)}</option>`).join('')}</select>`:''}</div>`;}
 fileRow(f){return `<div class="local-file-row"><button class="local-file-open" data-file-open="${f.id}" title="${esc(f.path)}">${svg(f.kind==='sheet'?'clipboard':'folder')}<span><b>${esc(f.name)}</b><small>${esc([f.source,f.stage,f.version].filter(Boolean).join(' · '))}${f.borrowed?' · 原项目 '+esc(f.projectCode):''}</small></span></button>${this.category==='borrow'&&this.code&&f.projectCode!==this.code&&!f.linkedCodes?.includes(this.code)?`<button class="button" data-file-borrow="${f.id}" aria-label="引用 ${esc(f.name)} 到 ${esc(this.code)}">引用</button>`:''}<button class="file-icon-button" data-file-reveal="${f.id}" aria-label="在 Finder 中显示 ${esc(f.name)}" title="在 Finder 中显示">${svg('folder')}</button></div>`;}
 body(){const files=this.files();
  if(!this.desktop?.files)return '<div class="file-empty">自动归集与打开本机文件，请使用桌面应用。</div>';
  if(!files.length)return `<div class="file-empty">${this.data.scanning?'正在扫描文件…':this.category==='pending'?'没有待确认的文件':'此项目还没有关联文件'}<button class="button" data-file-add-root>选择项目目录</button></div>`;
  if(this.category==='pending')return files.slice(0,300).map(f=>`<div class="file-pending">${this.fileRow(f)}<p>${esc(f.reason)}${f.contentNote?' · '+esc(f.contentNote):''}</p><div><select data-file-assignment="${f.id}" aria-label="${esc(f.name)} 所属项目"><option value="">选择项目</option>${this.data.projects.map(p=>`<option value="${esc(p.code)}">${esc(p.code+' · '+p.name)}</option>`).join('')}</select><button class="button" data-file-assign="${f.id}">确认归属</button></div></div>`).join('')+(files.length>300?'<div class="file-empty">前 300 份，输入文件名继续查找</div>':'');
  const groups=new Map();for(const f of files){const key=(f.borrowed?f.projectCode+' / ':'')+(f.material||f.name);if(!groups.has(key))groups.set(key,[]);groups.get(key).push(f);}
  return [...groups].map(([material,items])=>items.length===1?this.fileRow(items[0]):`<details class="file-version-group" data-file-group="${esc(material)}" ${this.openGroups.has(material)?'open':''}><summary>${svg('logo')}<span>${esc(material)}</span><small>${items.length} 份</small></summary><div>${items.map(f=>this.fileRow(f)).join('')}</div></details>`).join('');
 }
 sources(){return `<div class="file-source-settings">${this.data.roots.map(r=>`<label><span>${svg('folder')}<b>${esc(r.label)}</b><small>${esc(r.path)}</small></span><input type="checkbox" data-file-root="${r.id}" aria-label="监听 ${esc(r.label)}" ${r.enabled?'checked':''}></label>`).join('')}<button class="button" data-file-add-root>选择项目总目录</button><div class="file-model-state"><b>${esc(models[this.data.model.state]||'模型状态待确认')}</b><small>${this.data.modelBusy?'正在识别文件 · '+this.data.queued+' 份待处理':'项目号明确的文件直接按规则归集'}</small><button class="button" data-file-model>检查本地模型</button></div><button class="button" data-file-rescan ${this.data.scanning?'disabled':''}>${this.data.scanning?'正在扫描…':'重新扫描文件'}</button>${this.data.errors.map(e=>`<p class="file-source-error">${esc([e.source,e.error].filter(Boolean).join('：'))}</p>`).join('')}</div>`;}
 render(){return `<div class="view file-workspace">${this.toolbar()}${this.settings?this.sources():this.tabs()+this.searchBar()+'<div class="file-list" data-file-body>'+this.body()+'</div>'}</div>`;}
 paintPeek(){const target=document.getElementById('filePeek');const focused=target.querySelector('[data-library-search]')===document.activeElement;const selection=focused?document.activeElement.selectionStart:null;target.innerHTML=this.toolbar(true)+(this.settings?this.sources():this.tabs()+this.searchBar()+'<div class="file-list" data-file-body>'+this.body()+'</div>');target.hidden=false;if(focused){const input=target.querySelector('[data-library-search]');input.focus();try{input.setSelectionRange(selection,selection);}catch{}}}
 paintBody(){document.querySelectorAll('[data-file-body]').forEach(el=>{el.innerHTML=this.body();});}
 async click(event){const b=event.target.closest('button');if(!b)return;
  try{
   if(b.dataset.fileProject!==undefined){await this.show(b.dataset.fileProject);return;}
   if(b.dataset.fileOpen){await this.desktop.files('open',{id:b.dataset.fileOpen});return;}
   if(b.dataset.fileReveal){await this.desktop.files('reveal',{id:b.dataset.fileReveal});return;}
   if(b.dataset.fileBorrow){await this.desktop.files('borrow',{id:b.dataset.fileBorrow,code:this.code});await this.load();return;}
   if(b.dataset.fileCategory){this.category=b.dataset.fileCategory;this.settings=false;this.search='';this.peekOpen?this.paintPeek():this.refresh();return;}
   if(b.hasAttribute('data-file-settings')){await this.showSettings();return;}
   if(b.hasAttribute('data-file-close')){this.applyLayout(await this.desktop.layout({peek:false}));return;}
   if(b.hasAttribute('data-file-add-root')){b.disabled=true;try{this.data=await this.desktop.files('choose-root');await this.load();}finally{b.disabled=false;}return;}
   if(b.hasAttribute('data-file-rescan')){b.disabled=true;await this.desktop.files('scan');await this.load();return;}
   if(b.hasAttribute('data-file-model')){b.disabled=true;await this.desktop.files('model-start');await this.load();return;}
   if(b.dataset.fileAssign){const code=b.closest('.file-pending').querySelector('select').value;if(!code){this.notify('先选择所属项目');return;}await this.desktop.files('assign',{id:b.dataset.fileAssign,code});await this.load();return;}
   if(b.dataset.railAction){const action=b.dataset.railAction;if(action==='files')await this.show();else if(action==='pending')await this.show('', 'pending');else if(action==='settings')await this.showSettings();else if(action==='theme')document.dispatchEvent(new CustomEvent('review:toggle-theme'));else if(action==='search'){await this.show();(this.peekOpen?document.getElementById('filePeek'):document.getElementById('viewRoot')).querySelector('[data-library-search]')?.focus();}else{if(this.mode!=='workspace')await this.setMode('workspace');this.setView(action==='review'?'review':'home');}}
  }catch(e){this.notify(e.message);}
 }
 async change(event){const target=event.target;try{if(target.dataset.fileRoot){await this.desktop.files('toggle-root',{id:target.dataset.fileRoot,enabled:target.checked});await this.load();}if(target.hasAttribute('data-file-project-select')){this.code=target.value;this.peekOpen?this.paintPeek():this.refresh();}}catch(e){this.notify(e.message);}}
}
